const categories=['Todos los platos','Para compartir','Arroces','Carnes','Pescados','Postres','Vinos y bebidas'];let selected=categories[0],items=[];const input=document.querySelector('#search'),panel=document.querySelector('#categories'),toggle=document.querySelector('#category-button'),grid=document.querySelector('#dishes'),dialog=document.querySelector('dialog');const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();function close(){panel.hidden=true;toggle.setAttribute('aria-expanded','false')}toggle.onclick=()=>{panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',String(!panel.hidden))};categories.forEach(category=>{const button=document.createElement('button');button.textContent=category;button.setAttribute('aria-pressed',String(category===selected));button.onclick=()=>{selected=category;document.querySelector('#selected').textContent=category;panel.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));close();render();toggle.focus()};panel.append(button)});document.addEventListener('click',e=>{if(!e.target.closest('.category'))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});function render(){const filtered=items.filter(i=>(selected===categories[0]||i.category===selected)&&normalize(i.name).includes(normalize(input.value.trim())));grid.replaceChildren(...filtered.map(item=>{const button=document.createElement('button');button.className='dish';const img=document.createElement('img');img.src=item.image;img.alt='';img.loading='lazy';img.width=480;img.height=480;const text=document.createElement('span');text.textContent=item.name;button.append(img,text);button.onclick=()=>{dialog.querySelector('img').src=item.image;dialog.querySelector('img').alt=item.name;dialog.querySelector('h2').textContent=item.name;dialog.querySelector('p').textContent=item.note;dialog.showModal();document.body.style.overflow='hidden'};return button}));document.querySelector('#status').textContent=filtered.length+' propuestas · '+selected;document.querySelector('#empty').hidden=filtered.length>0}input.addEventListener('input',render);dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>document.body.style.overflow='');dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});fetch('/carta/menu.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{items=data;render()}).catch(()=>{document.querySelector('#status').textContent='No se ha podido cargar la carta. Recarga la página.'});
